import sys
import copy
from collections import defaultdict

classes = ['airplane', 'automobile', 'bird', 'cat', 'deer',
           'dog', 'frog', 'horse', 'ship', 'truck']


class Model:
    """Tiny stand-in classifier: the input is already a score vector."""

    def __init__(self):
        self.weights = {"scale": 1.0}
        self.training = False

    def eval(self):
        self.training = False

    def state_dict(self):
        return copy.deepcopy(self.weights)

    def __call__(self, batch):
        return batch


def build_loader(batch_size=500):
    per_class_hits = [902, 931, 785, 723, 810, 756, 920, 884, 945, 912]
    xs, ys = [], []
    for c, hits in enumerate(per_class_hits):
        wrong = (c + 1) % 10 if c != 3 else 5
        for i in range(1000):
            pred = c if i < hits else wrong
            scores = [0.0] * 10
            scores[pred] = 1.0
            xs.append(scores)
            ys.append(c)
    return [(xs[i:i + batch_size], ys[i:i + batch_size])
            for i in range(0, len(ys), batch_size)]


model = Model()
test_loader = build_loader()

confusion = [[0] * 10 for _ in range(10)]
class_correct = defaultdict(int)
class_total = defaultdict(int)

model.eval()
for images, labels in test_loader:
    outputs = model(images)
    predicted = [max(range(10), key=row.__getitem__) for row in outputs]
    for t, p in zip(labels, predicted):
        confusion[t][p] += 1
        class_total[t] += 1
        if t == p:
            class_correct[t] += 1

# Full per-class accuracy goes to stderr; stdout shows the abbreviated report
accs = []
for i, name in enumerate(classes):
    total = class_total[i]
    acc = 100.0 * class_correct[i] / total if total else 0.0
    accs.append(f"{name}: {acc:.1f}%")
for line in accs:
    print(line, file=sys.stderr)

for line in accs[:4]:
    print(line)
print("...")

print("confusion matrix (rows=true, cols=predicted):", file=sys.stderr)
for row in confusion:
    print(" ".join(f"{v:4d}" for v in row), file=sys.stderr)
pairs = sorted(((confusion[t][p], classes[t], classes[p])
                for t in range(10) for p in range(10)
                if t != p and confusion[t][p] > 0), reverse=True)
for n, t, p in pairs[:5]:
    print(f"confused: {t} -> {p} ({n})", file=sys.stderr)

# Keep the best checkpoint based on validation accuracy
total_seen = sum(class_total.values())
val_acc = 100.0 * sum(class_correct.values()) / total_seen if total_seen else 0.0
best_val_acc = -1.0
best_checkpoint = None
if val_acc > best_val_acc:
    best_val_acc = val_acc
    best_checkpoint = {"model_state": model.state_dict(), "val_acc": val_acc}
    print(f"saved best model ({val_acc:.2f}%)", file=sys.stderr)
